async function refreshHomeChecks(){const host=document.getElementById('home-visual-checks');if(!host)return;const binding=state.workspace?.workspaceRoot;if(!bridge()||!binding){host.replaceChildren();return;}try{const list=await invoke('workspace','list',{collection:'checks'});if(binding!==state.workspace?.workspaceRoot)return;homeCheckRecords=list.records||[];paintHomeChecks();}catch(error){host.textContent='Your visual tests could not be loaded. Open Project setup and check your folder. '+error.message;}}
function paintHomeChecks(){const host=document.getElementById('home-visual-checks');if(!host)return;const search=(document.getElementById('suite-search')?.value||'').toLowerCase(),language=document.getElementById('language-filter')?.value||'',tag=document.getElementById('tag-filter')?.value||'',sort=document.getElementById('sort-option')?.value||'dateModified';const records=homeCheckRecords.filter(r=>r.value.hiddenFromLibrary!==true&&String(r.value.name||'').toLowerCase().includes(search)&&(!language||((r.value.engine||'javascript')===language||(language==='website'&&r.value.engine==='playwright')))&&(!tag||(r.value.tags||[]).includes(tag)));const date=r=>Date.parse(sort==='dateCreated'?(r.value.createdAt||r.value.dateCreated||r.modified):(r.modified||r.value.dateModified))||0;records.sort((a,b)=>sort==='name'?String(a.value.name||'').localeCompare(String(b.value.name||'')):sort==='favorites'?Number(!!b.value.isFavorite)-Number(!!a.value.isFavorite)||String(a.value.name||'').localeCompare(String(b.value.name||'')):date(b)-date(a));host.innerHTML=homeCheckRecords.some(r=>r.value.hiddenFromLibrary!==true)?'<h2 class="text-2xl font-bold aero-text-primary">Visual tests</h2>'+records.map(r=>`<article class="aero-card lvx-home-check"><div><h3>${esc(r.value.name||'Untitled test')}</h3><p>${esc(r.value.engine||'javascript')} · ${r.value.steps?.length||0} steps</p></div><div><button class="aero-button-info" type="button" data-home-check="${esc(r.id)}">${icon('edit')} Edit</button><button class="aero-button-primary" type="button" data-home-check="${esc(r.id)}" data-home-run="true">${icon('play')} Run</button></div></article>`).join('')+(records.length?'':'<p>No visual tests match these filters.</p>'):'';}
