function resultView(result){const issues=result.errors||[];const findings=result.findings||[];const invalid=result.invalidRows??result.invalid??0;const total=result.totalRows??result.total??result.rows?.length;const success=result.valid===true||result.status==='SUCCESS'||(typeof total==='number'&&!invalid&&!issues.length);return `<p class="studio-result-status"><strong>${esc(result.status||(success?'Ready':issues.length||invalid?'Needs attention':'Result available'))}</strong>${total!==undefined?` · ${esc(total)} rows checked`:''}${invalid?` · ${esc(invalid)} rows need correction`:''}</p>${issues.length?`<ul>${issues.slice(0,30).map(e=>`<li>${typeof e==='string'?esc(e):`${e.row?'Row '+esc(e.row)+', ':''}${esc(e.column||e.code||'')}: ${esc(e.message||JSON.stringify(e))}`}</li>`).join('')}</ul>`:''}${findings.length?`<div class="studio-table-scroll"><table><caption>Findings</caption><thead><tr><th>Severity</th><th>Location</th><th>What to review</th></tr></thead><tbody>${findings.slice(0,100).map(f=>`<tr><td>${esc(f.severity)}</td><td>${esc(f.path||f.package||'')}${f.line?':'+esc(f.line):''}</td><td>${esc(f.message||f.summary||f.ruleId)}${f.suppressed?' (reviewed suppression)':''}</td></tr>`).join('')}</tbody></table></div>`:''}${result.coverage?`<p>Coverage: ${result.coverage.complete?'complete for the stated rules':'incomplete — this result cannot pass a gate'}</p>`:''}${evidence(result)}`;}
function rowsView(rows){if(!Array.isArray(rows)||!rows.length)return '';const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))].slice(0,15);return `<div class="studio-table-scroll"><table><caption>Preview — first ${Math.min(20,rows.length)} of ${rows.length} rows</caption><thead><tr>${keys.map(k=>`<th>${esc(k)}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,20).map(row=>`<tr>${keys.map(k=>`<td>${esc(row[k])}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
